/* ============================================================================
Merchant Sales-Based Financing Strategy Simulator
Module 2.6 — Early Warning, Intervention & Servicing Strategy

Program     : 175_msbf_m2_6_intervention_strategy_validation_v0_2.sql
Version     : v0.2

Purpose
-------
Execute 120 read-only positive controls across lifecycle, source lineage,
policy boundaries, reference dictionaries, strategy mapping, review terms,
recommendation-only flags, hashes, latest/archive reproduction, stress
non-improvement, and acceptance readiness.

Required result
---------------
120 / 120 PASS and run_status = M2_6_VALIDATED.
============================================================================ */
BEGIN;
SET LOCAL statement_timeout='45min'; SET LOCAL work_mem='128MB'; SET LOCAL jit=off;
DROP TABLE IF EXISTS _m2_6_validation;
CREATE TEMP TABLE _m2_6_validation(evidence_code text PRIMARY KEY, metric_name text, observed_value text, threshold_value text, status text, interpretation text) ON COMMIT PRESERVE ROWS;
DROP TABLE IF EXISTS _m2_6_vctx;
CREATE TEMP TABLE _m2_6_vctx ON COMMIT DROP AS SELECT run_id, run_status FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1;
DO $ready$ BEGIN PERFORM msbf_ctl.m2_6_assert_validation_ready((SELECT run_id FROM _m2_6_vctx)); END; $ready$;
CREATE OR REPLACE FUNCTION pg_temp.m2_6_add_check(p_code text,p_metric text,p_observed text,p_threshold text,p_pass boolean,p_interpretation text) RETURNS void LANGUAGE plpgsql AS $function$ BEGIN INSERT INTO _m2_6_validation VALUES(p_code,p_metric,p_observed,p_threshold,CASE WHEN p_pass THEN 'PASS' ELSE 'FAIL' END,p_interpretation); END; $function$;
DO $checks$ BEGIN
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_001_RUN_STATUS','RUN_STATUS',((SELECT run_status FROM _m2_6_vctx))::text,'M2_6_GENERATED|M2_6_VALIDATED',coalesce(((SELECT run_status IN ('M2_6_GENERATED','M2_6_VALIDATED') FROM _m2_6_vctx)),FALSE),'Validation begins from aligned generated or validated state.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_002_CONTRACT_STATUS','CONTRACT_STATUS',((SELECT contract_status FROM msbf_ctl.m2_6_intervention_strategy_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'GENERATED|VALIDATED',coalesce(((SELECT contract_status IN ('GENERATED','VALIDATED') FROM msbf_ctl.m2_6_intervention_strategy_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'Contract is aligned with validation state.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_003_POLICY_APPROVED','POLICY_STATUS',((SELECT policy_status FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'APPROVED',coalesce(((SELECT policy_status='APPROVED' FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'M2.6 policy is approved.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_004_POLICY_BOUNDARIES','POLICY_BOUNDARIES',((SELECT recommendation_only_flag||'|'||no_merchant_contact_execution_flag||'|'||no_payment_change_execution_flag||'|'||no_write_off_charge_off_execution_flag||'|'||no_legal_or_collection_action_flag||'|'||no_external_notice_generation_flag||'|'||no_production_adverse_action_notice_flag FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'all true',coalesce(((SELECT recommendation_only_flag AND no_merchant_contact_execution_flag AND no_payment_change_execution_flag AND no_write_off_charge_off_execution_flag AND no_legal_or_collection_action_flag AND no_external_notice_generation_flag AND no_production_adverse_action_notice_flag FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'All recommendation-only stage boundaries are true.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_005_SOURCE_HASH','SOURCE_M2_5_HASH',((SELECT source_m2_5_combined_hash FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'18e1c444aa1b02ee5bd3539d7c477adc',coalesce(((SELECT source_m2_5_combined_hash='18e1c444aa1b02ee5bd3539d7c477adc' FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'Accepted M2.5 hash is frozen.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_006_CONFIGURATION_HASH','CONFIGURATION_HASH',((SELECT configuration_hash FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'physical reconstruction',coalesce(((SELECT configuration_hash=msbf_ctl.m2_6_hash_jsonb(configuration_payload) FROM msbf_ctl.m2_6_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'Policy configuration hash reconstructs.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_007_OUTCOME_COUNT','OUTCOME_COUNT',((SELECT count(*) FROM msbf_m2.intervention_strategy_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'7',coalesce(((SELECT count(*)=7 FROM msbf_m2.intervention_strategy_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'OUTCOME_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_008_ACTION_COUNT','ACTION_COUNT',((SELECT count(*) FROM msbf_m2.intervention_servicing_action_definition WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'7',coalesce(((SELECT count(*)=7 FROM msbf_m2.intervention_servicing_action_definition WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'ACTION_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_009_REASON_COUNT','REASON_COUNT',((SELECT count(*) FROM msbf_m2.intervention_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'30',coalesce(((SELECT count(*)=30 FROM msbf_m2.intervention_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'REASON_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_010_SOURCE_COUNT','SOURCE_COUNT',((SELECT count(*) FROM msbf_m2.advance_intervention_source_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'59',coalesce(((SELECT count(*)=59 FROM msbf_m2.advance_intervention_source_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'SOURCE_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_011_STRATEGY_COUNT','STRATEGY_COUNT',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'59',coalesce(((SELECT count(*)=59 FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'STRATEGY_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_012_PORTFOLIO_SUMMARY_COUNT','PORTFOLIO_SUMMARY_COUNT',((SELECT count(*) FROM msbf_m2.portfolio_intervention_strategy_summary WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'2',coalesce(((SELECT count(*)=2 FROM msbf_m2.portfolio_intervention_strategy_summary WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'PORTFOLIO_SUMMARY_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_013_LATEST_COUNT','LATEST_COUNT',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'59',coalesce(((SELECT count(*)=59 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'LATEST_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_014_ARCHIVE_COUNT','ARCHIVE_COUNT',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_archive WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'59',coalesce(((SELECT count(*)=59 FROM msbf_m2.advance_intervention_strategy_archive WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'ARCHIVE_COUNT matches expected count.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_015_COMPARISON_COUNT','COMPARISON_COUNT',((SELECT count(*) FROM msbf_m2.v_m2_6_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'15',coalesce(((SELECT count(*)=15 FROM msbf_m2.v_m2_6_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'Matched comparisons count is 15.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_016_CLOSED_ROWS','CLOSED_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='CLOSED_NO_FURTHER_ACTION'))::text,'57',coalesce(((SELECT count(*)=57 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='CLOSED_NO_FURTHER_ACTION')),FALSE),'CLOSED_NO_FURTHER_ACTION count is expected.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_017_CONTINUE_ROWS','CONTINUE_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='CONTINUE_STANDARD_MONITORING'))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='CONTINUE_STANDARD_MONITORING')),FALSE),'CONTINUE_STANDARD_MONITORING count is expected.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_018_OUTREACH_ROWS','OUTREACH_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='TARGETED_MERCHANT_OUTREACH_REVIEW'))::text,'1',coalesce(((SELECT count(*)=1 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='TARGETED_MERCHANT_OUTREACH_REVIEW')),FALSE),'TARGETED_MERCHANT_OUTREACH_REVIEW count is expected.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_019_TEMP_ROWS','TEMP_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='TEMPORARY_REMITTANCE_ADJUSTMENT_REVIEW'))::text,'1',coalesce(((SELECT count(*)=1 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='TEMPORARY_REMITTANCE_ADJUSTMENT_REVIEW')),FALSE),'TEMPORARY_REMITTANCE_ADJUSTMENT_REVIEW count is expected.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_020_WORKOUT_ROWS','WORKOUT_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='WORKOUT_RESTRUCTURE_REVIEW'))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='WORKOUT_RESTRUCTURE_REVIEW')),FALSE),'WORKOUT_RESTRUCTURE_REVIEW count is expected.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_021_RECOVERY_ROWS','RECOVERY_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='CONTROLLED_EXIT_RECOVERY_REVIEW'))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='CONTROLLED_EXIT_RECOVERY_REVIEW')),FALSE),'CONTROLLED_EXIT_RECOVERY_REVIEW count is expected.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_022_MANUAL_ROWS','MANUAL_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='MANUAL_GOVERNANCE_REVIEW'))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND strategy_outcome_code='MANUAL_GOVERNANCE_REVIEW')),FALSE),'MANUAL_GOVERNANCE_REVIEW count is expected.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_023_RECOMMENDED_ACTION_ROWS','RECOMMENDED_ACTION_ROWS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND recommended_action_flag))::text,'2',coalesce(((SELECT count(*)=2 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND recommended_action_flag)),FALSE),'Two recommendation-review rows exist.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_024_RECOMMENDED_EXPOSURE','RECOMMENDED_ACTION_EXPOSURE',((SELECT round(sum(recommended_action_exposure_amount),2) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'979.73',coalesce(((SELECT round(sum(recommended_action_exposure_amount),2)=979.73 FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'Recommended-action exposure reconciles.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_025_SOURCE_GRAIN','SOURCE_GRAIN_DUPLICATES',((SELECT count(*)-count(DISTINCT scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_source_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_source_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'SOURCE_GRAIN is unique.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_026_STRATEGY_GRAIN','STRATEGY_GRAIN_DUPLICATES',((SELECT count(*)-count(DISTINCT scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'STRATEGY_GRAIN is unique.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_027_LATEST_GRAIN','LATEST_GRAIN_DUPLICATES',((SELECT count(*)-count(DISTINCT scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'LATEST_GRAIN is unique.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_028_ARCHIVE_GRAIN','ARCHIVE_GRAIN_DUPLICATES',((SELECT count(*)-count(DISTINCT contract_version::text||'|'||scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_strategy_archive WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx)))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT contract_version::text||'|'||scenario_id::text||'|'||merchant_application_id) FROM msbf_m2.advance_intervention_strategy_archive WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx))),FALSE),'ARCHIVE_GRAIN is unique.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_029_NO_EXECUTED_FLAGS','NO_EXECUTED_FLAGS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND (merchant_contact_executed_flag OR payment_change_executed_flag OR write_off_or_charge_off_executed_flag OR legal_or_collection_action_executed_flag OR external_notice_generated_flag OR production_adverse_action_notice_flag)))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND (merchant_contact_executed_flag OR payment_change_executed_flag OR write_off_or_charge_off_executed_flag OR legal_or_collection_action_executed_flag OR external_notice_generated_flag OR production_adverse_action_notice_flag))),FALSE),'No executed servicing or notice flags exist.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_030_TEMP_TERMS_PRESENT','TEMP_TERMS_PRESENT',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND temporary_adjustment_review_flag AND temporary_remittance_rate_factor=0.75 AND recommended_review_duration_days=14 AND reassessment_interval_days=7))::text,'1',coalesce(((SELECT count(*)=1 FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND temporary_adjustment_review_flag AND temporary_remittance_rate_factor=0.75 AND recommended_review_duration_days=14 AND reassessment_interval_days=7)),FALSE),'Temporary review terms are present for one row.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_031_NON_TEMP_TERMS_NULL','NON_TEMP_TERMS_NULL',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND NOT temporary_adjustment_review_flag AND (temporary_remittance_rate_factor IS NOT NULL OR review_remittance_rate IS NOT NULL OR recommended_review_duration_days IS NOT NULL OR reassessment_interval_days IS NOT NULL)))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND NOT temporary_adjustment_review_flag AND (temporary_remittance_rate_factor IS NOT NULL OR review_remittance_rate IS NOT NULL OR recommended_review_duration_days IS NOT NULL OR reassessment_interval_days IS NOT NULL))),FALSE),'Non-temporary outcomes carry no temporary review terms.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_032_REASON_ARRAY','REASON_ARRAY_ERRORS',((SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND (jsonb_typeof(intervention_reason_codes)<>'array' OR jsonb_array_length(intervention_reason_codes)=0)))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND (jsonb_typeof(intervention_reason_codes)<>'array' OR jsonb_array_length(intervention_reason_codes)=0))),FALSE),'Reason arrays are nonempty JSON arrays.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_033_PAID_SOURCE_CLOSED','PAID_SOURCE_CLOSED_MISMATCHES',((SELECT count(*) FROM msbf_m2.advance_intervention_source_snapshot AS source JOIN msbf_m2.advance_intervention_strategy_snapshot AS strategy ON strategy.module1_run_id=source.module1_run_id AND strategy.scenario_id=source.scenario_id AND strategy.merchant_application_id=source.merchant_application_id WHERE source.module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND source.paid_off_flag AND strategy.strategy_outcome_code<>'CLOSED_NO_FURTHER_ACTION'))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_source_snapshot AS source JOIN msbf_m2.advance_intervention_strategy_snapshot AS strategy ON strategy.module1_run_id=source.module1_run_id AND strategy.scenario_id=source.scenario_id AND strategy.merchant_application_id=source.merchant_application_id WHERE source.module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND source.paid_off_flag AND strategy.strategy_outcome_code<>'CLOSED_NO_FURTHER_ACTION')),FALSE),'Paid-off source maps to closed no action.');
    PERFORM pg_temp.m2_6_add_check('M2_6_POS_034_OPEN_SOURCE_RECOMMENDED','OPEN_SOURCE_RECOMMENDED_MISMATCHES',((SELECT count(*) FROM msbf_m2.advance_intervention_source_snapshot AS source JOIN msbf_m2.advance_intervention_strategy_snapshot AS strategy ON strategy.module1_run_id=source.module1_run_id AND strategy.scenario_id=source.scenario_id AND strategy.merchant_application_id=source.merchant_application_id WHERE source.module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND NOT source.paid_off_flag AND NOT strategy.recommended_action_flag))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.advance_intervention_source_snapshot AS source JOIN msbf_m2.advance_intervention_strategy_snapshot AS strategy ON strategy.module1_run_id=source.module1_run_id AND strategy.scenario_id=source.scenario_id AND strategy.merchant_application_id=source.merchant_application_id WHERE source.module1_run_id=(SELECT run_id FROM _m2_6_vctx) AND NOT source.paid_off_flag AND NOT strategy.recommended_action_flag)),FALSE),'Open source records map to recommended reviews.');
