DO $final$ DECLARE v_total bigint; v_pass bigint; v_fail bigint; BEGIN SELECT count(*), count(*) FILTER (WHERE status='PASS'), count(*) FILTER (WHERE status='FAIL') INTO v_total, v_pass, v_fail FROM _m2_6_validation; IF v_total<>120 THEN RAISE EXCEPTION 'M2.6 positive-control inventory failed: total %, expected 120.', v_total; END IF; INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_numeric,metric_value_text,unit_code,status,interpretation) SELECT (SELECT run_id FROM _m2_6_vctx), evidence_code, 'PORTFOLIO', metric_name, NULL::numeric(28,10), coalesce(observed_value,'<NULL>'), 'VALIDATION', status, interpretation||' Threshold: '||coalesce(threshold_value,'<NULL>') FROM _m2_6_validation ON CONFLICT(run_id,evidence_code,segment_key) DO UPDATE SET metric_name=EXCLUDED.metric_name, metric_value_numeric=NULL, metric_value_text=EXCLUDED.metric_value_text, unit_code=EXCLUDED.unit_code, status=EXCLUDED.status, interpretation=EXCLUDED.interpretation, created_at=clock_timestamp(); IF v_pass=120 AND v_fail=0 THEN UPDATE msbf_ctl.run_registry SET run_status='M2_6_VALIDATED' WHERE run_id=(SELECT run_id FROM _m2_6_vctx); UPDATE msbf_ctl.m2_6_intervention_strategy_contract_registry SET contract_status='VALIDATED', validated_at=clock_timestamp() WHERE module1_run_id=(SELECT run_id FROM _m2_6_vctx); ELSE RAISE EXCEPTION 'M2.6 positive validation failed: pass %, fail %.', v_pass, v_fail; END IF; END; $final$;
COMMIT;
SELECT * FROM _m2_6_validation ORDER BY evidence_code;
